import abc
import re

import six
from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand


@six.add_metaclass(abc.ABCMeta)
class GenericTabContent(GenericEPCSIMCommand):
    """Generictabcontent command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Generictabcontent command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GenericTabContent, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.titles = ""
        self.headers = []
        self.starts = []
        self.headers_col_count = 0
        self._add_list = False
        self._add_dict = True

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_failure(line)
                self._parse_titles(line)
                self._parse_headers(line)
                self._parse_data_row(line)
            except ParsingDone:
                pass  # line has been fully parsed by one of above parse-methods
        return super(GenericTabContent, self).on_new_line(line, is_full_line)

    _re_failure1 = re.compile(r"The command is not allowed")
    _re_failure2 = re.compile(r"Error:|ERR:")

    def _parse_failure(self, line):
        if self._regex_helper.search_compiled(GenericTabContent._re_failure1, line) or self._regex_helper.search_compiled(
            GenericTabContent._re_failure2, line
        ):
            self.set_exception(CommandFailure(self, f"Error: {line}"))
            raise ParsingDone

    def _parse_titles(self, line):
        if not self.titles:
            matched = re.findall(r"Configured (\S+)\s*", line)
            if matched:
                self.titles = matched
                raise ParsingDone()

    _re_data_header = re.compile(r"\S+\s{2,}\S+")

    def _parse_headers(self, line):
        if 0 == self.headers_col_count and re.search(GenericTabContent._re_data_header, line):
            fields = re.split(r"\s{2,}", line)
            if fields:
                self.headers = []
                self.starts = []
                last_index = 0
                for field in fields:
                    self.headers.append(field)
                    last_index = line.index(field, last_index)
                    self.starts.append(last_index)
                self.headers_col_count = len(self.headers)
                raise ParsingDone()

    def _parse_data_row(self, line):
        if self.headers_col_count and (self.headers_col_count == len(re.split(r"\s{2,}", line))) and (len(line) >= self.starts[-1]):
            key = None
            parsed_values = None
            for i in range(0, self.headers_col_count, 1):
                if i == self.headers_col_count - 1:
                    last = len(line)
                else:
                    last = self.starts[i + 1]
                value = line[self.starts[i]: last]
                value = value.strip()
                if not key:
                    key = value
                    parsed_values = {}
                parsed_values[self.headers[i]] = value
            if parsed_values:
                if self._add_list:
                    if "LIST" not in self.current_ret:
                        self.current_ret["LIST"] = []
                    self.current_ret["LIST"].append(parsed_values)
                if self._add_dict:
                    if "DICT" not in self.current_ret:
                        self.current_ret["DICT"] = {}
                    self.current_ret["DICT"][key] = parsed_values
            raise ParsingDone()
